sys_script_client.script:
//SN5106 - Dynamic Prioritization
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue == oldValue || !newValue) {
        return;
    }

    if (newValue == '16b78ea11b0d2d506ed00e1ad34bcb05') { //Gross Consideration
        g_form.hideAllFieldMsgs();
        g_form.showFieldMsg('u_fff', 'Please enter a numeric value. The value will be considered in USD. For example, enter "1000000" for 1 million USD.', 'info');
    } else if (newValue == '0857ce611b0d2d506ed00e1ad34bcbd9') { //Buy/Sell
        g_form.hideAllFieldMsgs();
        g_form.showFieldMsg('u_fff', 'Enter "B" for Buy or "S" for Sale as the value.', 'info');
    } else if (newValue == '71abf0db1bc525906ed00e1ad34bcb69' || newValue == 'f10cfcdb1bc525906ed00e1ad34bcbae') { //Value/Trade Date
        g_form.hideAllFieldMsgs();
        g_form.showFieldMsg('u_fff', 'Enter a value in the format: >-1, <-1, >+2, <-2, >+0, <+0, =+1, =+0, etc.', 'info');
        g_form.showFieldMsg('u_fff', 'For example: ">-1" means greater than yesterday\'s date, "<-1" means less than yesterday\'s date, ">+0" means greater than today\'s date, "<+0" means less than today\'s date, "=+0" means equals to today\'s date, ">+2" means greater than the date two days from today, and "<+2" means less than the date two days from today.', 'info');
    } else if (newValue == 'b788979f97fd691098717fb71153af2d') { //Stock Connect Trade
        g_form.hideAllFieldMsgs();
        g_form.showFieldMsg('u_fff', 'Enter "Yes" if it is a Stock Connect trade, otherwise enter "No".', 'info');
    } else if (newValue == '2fe806651b0d2d506ed00e1ad34bcb82') { //counterparty ID 
        g_form.hideAllFieldMsgs();
        g_form.showFieldMsg('u_fff', 'Please enter a valid counterparty ID.', 'info');
    }

    var ga = new GlideAjax('x_hsb11_hsbc_mss_o.DynamicExpectedValueHelper');
    ga.addParam('sysparm_name', 'getExpectedValues');
    ga.addParam('sysparm_dict_sys_id', newValue);
    ga.getXMLAnswer(function(response) {
        var result = JSON.parse(response);

        // Check if the selected field is of type string
        if (result.type === 'string') {
			g_form.clearMessages();
            g_form.addInfoMessage('Selected field does not have any choices. Please enter value in free form field.');
            // Make 'expected_value' read-only and not mandatory
            setTimeout(function() {
                g_form.clearOptions('expected_value');
                g_form.setMandatory('expected_value', false);
                g_form.setReadOnly('expected_value', true);
            }, 100);
            setTimeout(function() {
                g_form.setReadOnly('u_fff', false);
                g_form.setMandatory('u_fff', true);
            }, 100);

            return; // Exit early since no further processing is needed
        } else {
            g_form.clearMessages();
			g_form.addInfoMessage('Selected field contains choices. Please select a desired choice from Expected Value dropdown');
            setTimeout(function() {
                g_form.setReadOnly('expected_value', false);
                g_form.setMandatory('expected_value', true);
            }, 100);
            setTimeout(function() {
                g_form.clearValue('u_fff');
                g_form.setMandatory('u_fff', false);
                g_form.setReadOnly('u_fff', true);

            }, 100);
        }

        // For debug: show all possible values in an alert
        if (result.values && result.values.length > 0) {
            var debugMsg = result.values.map(function(opt) {
                return opt.label + ' (' + opt.value + ')';
            }).join('\n');
            alert('Possible values:\n' + debugMsg);
        } else {
            alert('No possible values found for this field.');
        }


        // Try to update u_expected_value as a choice field
        try {
            g_form.clearOptions('expected_value');
            if (result.values && result.values.length > 0) {
                result.values.forEach(function(opt) {
                    g_form.addOption('expected_value', opt.value, opt.label);
                });
            }
        } catch (e) {
            // If not a choice field, show as info message instead
            g_form.hideFieldMsg('expected_value', true);
            if (result.values && result.values.length > 0) {
                var suggestions = result.values.map(function(opt) {
                    return opt.label;
                }).join(', ');
                g_form.showFieldMsg('expected_value', 'Possible values: ' + suggestions, 'info');
            }
        }
    });
}
